import React from 'react';

function Sidebar({ user, currentView, setCurrentView, onLogout }) {
  return (
    <div className="sidebar">
      <div className="sidebar-header">
        <h2>Task Calendar</h2>
        <div className="user-info">
          {user.name} ({user.role})
        </div>
      </div>
      <div className="sidebar-nav">
        <div
          className={`nav-item ${currentView === 'daily' ? 'active' : ''}`}
          onClick={() => setCurrentView('daily')}
        >
          📅 Daily Tasks
        </div>
        <div
          className={`nav-item ${currentView === 'weekly' ? 'active' : ''}`}
          onClick={() => setCurrentView('weekly')}
        >
          📊 Weekly Tasks
        </div>
        <div
          className={`nav-item ${currentView === 'monthly' ? 'active' : ''}`}
          onClick={() => setCurrentView('monthly')}
        >
          📈 Monthly Tasks
        </div>
        {user.role === 'admin' && (
          <>
            <div
              className={`nav-item ${currentView === 'calendar' ? 'active' : ''}`}
              onClick={() => setCurrentView('calendar')}
            >
              🗓️ Calendar View
            </div>
            <div
              className={`nav-item ${currentView === 'templates' ? 'active' : ''}`}
              onClick={() => setCurrentView('templates')}
            >
              ⚙️ Manage Templates
            </div>
          </>
        )}
      </div>
      <button className="logout-btn" onClick={onLogout}>
        Logout
      </button>
    </div>
  );
}

export default Sidebar;
